// Read-only independent protobuf-net reader using pinned public SimRipper
// generated game schemas. No game libraries, calls, UI or write operations.
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text.Json;using ProtoBuf;using EA.Sims4.Persistence;
class Program{
static void Main(){using var s=new MemoryStream();Console.OpenStandardInput().CopyTo(s);if(s.Length<8||s.Length>64*1024*1024)throw new Exception("bound");s.Position=0;using var r=new BinaryReader(s);uint version=r.ReadUInt32(),size=r.ReadUInt32();if(size!=s.Length-4)throw new Exception("wrapper size");int length;if(version==1){length=checked((int)s.Length-8);}else if(version==2){if(r.ReadUInt32()!=0)throw new Exception("reserved");length=checked((int)r.ReadUInt32());}else throw new Exception("version");var payload=r.ReadBytes(length);if(payload.Length!=length)throw new Exception("truncated");using var input=new MemoryStream(payload);var family=Serializer.Deserialize<EA.Sims4.Network.FamilyData>(input);var records=new List<object>();int si=0;foreach(var sim in family.family_account.sim){Emit(records,si,sim.sim_id,null,sim.outfits);var forms=sim.attributes?.occult_tracker?.occult_sim_infos;if(forms!=null)for(int i=0;i<forms.Count;i++)Emit(records,si,sim.sim_id,i,forms[i].outfits);si++;}Console.Write(JsonSerializer.Serialize(new{wrapperVersion=version,simCount=si,records}));}
static void Emit(List<object> records,int simIndex,ulong simId,int? form,OutfitList list){if(list==null)return;for(int i=0;i<list.outfits.Count;i++){var outfit=list.outfits[i];var ids=outfit.parts?.ids??Array.Empty<ulong>();var body=outfit.body_types_list?.body_types;var shifts=outfit.part_shifts?.color_shift;records.Add(new{sim_index=simIndex,sim_id=simId,occult_form_index=form,outfit_index=i,outfit_id=outfit.outfit_id,parts=ids,body_types=body,color_shifts=shifts,layer_wrapper_present=outfit.layer_ids!=null,layer_ids=outfit.layer_ids?.layer_id});}}
}
